-- Verify: this file owns exactly 514 rows for TD. The assertion counts only
-- rows whose path is declared in this file, so a correct re-run still passes even when
-- other rows exist for TD.
do $$
declare cnt integer;
begin
  select count(*) into cnt
  from public.locations
  where country_code = 'TD'
    and path = any (array[
      'chad',
      'chad/bahr-el-ghazel-province',
      'chad/bahr-el-ghazel-province/bahr-el-ghazel-north-and-west-area',
